--
-- Struktura tabeli dla tabeli `since-drift`
--

CREATE TABLE `since-drift` (
  `sid` bigint(20) NOT NULL,
  `pkt` bigint(20) NOT NULL,
  `login` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

